SELECT s.s_store_name, s.s_city, s.s_state, t.t_hour, COUNT(DISTINCT ca.ca_address_sk) AS num_customers, AVG(cd.cd_purchase_estimate) AS avg_purchase_estimate, SUM(cd.cd_dep_employed_count) AS total_dependent_employed, MIN(ca.ca_gmt_offset) AS min_gmt_offset, MAX(ca.ca_gmt_offset) AS max_gmt_offset FROM store s JOIN customer_address ca ON s.s_state = ca.ca_state AND s.s_city = ca.ca_city AND s.s_zip = ca.ca_zip JOIN customer_demographics cd ON cd.cd_demo_sk = ca.ca_address_sk JOIN time_dim t ON t.t_hour = ((12 + CAST(s.s_gmt_offset AS INTEGER)) % 24) WHERE ca.ca_country = 'United States' AND ca.ca_location_type IN ('condo', 'single family') AND s.s_closed_date_sk IS NULL GROUP BY s.s_store_name, s.s_city, s.s_state, t.t_hour HAVING COUNT(DISTINCT ca.ca_address_sk) >= 10 ORDER BY avg_purchase_estimate DESC, num_customers DESC LIMIT 100
